using System.Runtime.CompilerServices;

namespace TreeSpitter;

/// <summary>
/// A lexer automaton: for each state, the token it accepts, its transition at the end of the input and its transitions on
/// code points, the equivalent of the <c>ts_lex</c> function generated by tree-sitter. The transitions of the ASCII code
/// points are also stored in a dense table.
/// </summary>
internal sealed class LexAutomaton
{
    /// <summary>The flag of the transitions which skip the code point (separators, like white space).</summary>
    public const int SkipFlag = 1 << 30;

    public static readonly LexAutomaton Empty = new([], [], [0], [], [], []);

    public LexAutomaton(int[] accept, int[] eofTarget, int[] transitionStart, int[] rangeStart, int[] rangeEnd, int[] rangeTarget)
    {
        Accept = accept;
        EofTarget = eofTarget;
        TransitionStart = transitionStart;
        RangeStart = rangeStart;
        RangeEnd = rangeEnd;
        RangeTarget = rangeTarget;
        Ascii = new int[accept.Length * 128];
        for (var state = 0; state < accept.Length; state++)
        {
            for (var i = transitionStart[state]; i < transitionStart[state + 1]; i++)
            {
                for (var c = rangeStart[i]; c <= rangeEnd[i] && c < 128; c++)
                {
                    Ascii[state * 128 + c] = rangeTarget[i] + 1;
                }
            }
        }
    }

    public int StateCount => Accept.Length;

    /// <summary>The symbol accepted by each state, or -1.</summary>
    public int[] Accept { get; }

    /// <summary>The state reached at the end of the input, or -1.</summary>
    public int[] EofTarget { get; }

    /// <summary>The index of the first transition of each state in the range arrays, with a last entry for the end.</summary>
    public int[] TransitionStart { get; }

    /// <summary>The first code point of each transition.</summary>
    public int[] RangeStart { get; }

    /// <summary>The last code point (inclusive) of each transition.</summary>
    public int[] RangeEnd { get; }

    /// <summary>The target state of each transition, with <see cref="SkipFlag"/> for separators.</summary>
    public int[] RangeTarget { get; }

    /// <summary>[state * 128 + c]: the target of the transition on an ASCII code point plus one, or 0.</summary>
    public int[] Ascii { get; }

    /// <summary>The transition of a state on a code point: the target (with <see cref="SkipFlag"/>), or -1.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public int Transition(int state, int c)
    {
        if (c < 128)
        {
            return Ascii[(state << 7) + c] - 1;
        }

        return NonAsciiTransition(state, c);
    }

    private int NonAsciiTransition(int state, int c)
    {
        var low = TransitionStart[state];
        var high = TransitionStart[state + 1] - 1;
        while (low <= high)
        {
            var mid = (low + high) >> 1;
            if (c < RangeStart[mid])
            {
                high = mid - 1;
            }
            else if (c > RangeEnd[mid])
            {
                low = mid + 1;
            }
            else
            {
                return RangeTarget[mid];
            }
        }

        return -1;
    }
}
